function map(document) {
  const pairs = [];
  for (const word of document.text.split(/\s+/)) {
    pairs.push([word.toLowerCase(), 1]);
  }
  return pairs;   // e.g. [['the', 1], ['cat', 1], ['the', 1], ...]
}

function reduce(word, counts) {
  return [word, counts.reduce((sum, c) => sum + c, 0)];
}

// reduce('the', [1, 1, 1]) -> ['the', 3]

// NAIVE emission from map(): one pair per word occurrence, no local folding
// ['the',1] ['cat',1] ['the',1] ['sat',1] ['the',1] ...
// -> all of these cross the network individually during shuffle

function combine(pairs) {
  const local = new Map();
  for (const [word, count] of pairs) {
    local.set(word, (local.get(word) ?? 0) + count);
  }
  return [...local.entries()];   // one pair per distinct word, not per occurrence
}

function maybeSpeculate(task) {
  const isSlow = task.elapsed > 1.5 * medianTaskTime;
  if (isSlow && !task.hasSpeculativeCopy) {
    scheduler.launchDuplicate(task);   // race the original, take first result
  }
}
